function sv_visual_data_url(string $path,string $mime):?string{
    if(!extension_loaded('gd'))return null;$source=wt_load_gd_image($path,$mime);if(!$source)return null;
    $source=wt_apply_jpeg_orientation($source,$path,$mime);$w=imagesx($source);$h=imagesy($source);if($w<1||$h<1)return null;
    $scale=min(1,512/max($w,$h));$outW=max(1,(int)round($w*$scale));$outH=max(1,(int)round($h*$scale));
    $canvas=imagecreatetruecolor($outW,$outH);$white=imagecolorallocate($canvas,255,255,255);imagefilledrectangle($canvas,0,0,$outW,$outH,$white);imagecopyresampled($canvas,$source,0,0,0,0,$outW,$outH,$w,$h);
    ob_start();imagejpeg($canvas,null,68);$bytes=ob_get_clean();imagedestroy($canvas);if(is_resource($source)||is_object($source))@imagedestroy($source);
    return is_string($bytes)&&$bytes!==''?'data:image/jpeg;base64,'.base64_encode($bytes):null;
}
function sv_contact_sheet_data_urls(array $photos):array{
