        foreach($chunk as $i=>$photo){$path=wt_task_photo_path((string)$photo['relative_path']);if(!is_file($path))continue;$src=wt_load_gd_image($path,(string)$photo['mime_type']);if(!$src)continue;$src=wt_apply_jpeg_orientation($src,$path,(string)$photo['mime_type']);$sw=imagesx($src);$sh=imagesy($src);$scale=min(150/max(1,$sw),150/max(1,$sh));$dw=max(1,(int)round($sw*$scale));$dh=max(1,(int)round($sh*$scale));$x=($i%$cols)*$tileW+(int)(($tileW-$dw)/2);$y=(int)floor($i/$cols)*$tileH+(int)((155-$dh)/2);imagecopyresampled($sheet,$src,$x,$y,0,0,$dw,$dh,$sw,$sh);imagestring($sheet,2,($i%$cols)*$tileW+4,(int)floor($i/$cols)*$tileH+158,'#'.(int)$photo['id'].' '.strtoupper((string)$photo['photo_type']),$ink);@imagedestroy($src);}
        ob_start();imagejpeg($sheet,null,58);$bytes=ob_get_clean();imagedestroy($sheet);if(is_string($bytes)&&$bytes!=='')$sheets[]='data:image/jpeg;base64,'.base64_encode($bytes);
    }return $sheets;
}
